import socket,sqlite3,threading,os,time
DB='/app/data/huddle.db'
def conn():
 c=sqlite3.connect(DB);c.row_factory=sqlite3.Row;return c
def serve(cl):
 nick=None; user=None; token=None; registered=False; joined=set(); buf=b''
 def send(x):
  try: cl.sendall((x+'\r\n').encode())
  except: pass
 def register():
  nonlocal registered
  if registered:return
  c=conn(); r=c.execute('SELECT u.* FROM users u JOIN tokens t ON t.user_id=u.id WHERE t.token=?',(token,)).fetchone()
  if not r:return
  if c.execute('SELECT 1 FROM irc_nicks WHERE nick=?',(nick,)).fetchone(): send(':huddle 433 * '+nick+' :Nickname is already in use');return
  c.execute('INSERT OR IGNORE INTO irc_nicks VALUES(?)',(nick,));c.commit();registered=True
  for code,text in [('001','Welcome'),('002','Your host is huddle'),('003','This server was created today'),('004','huddle huddle'),('005','CHANTYPES=#')]:send(':huddle '+code+' '+nick+' :'+text)
  send(':huddle 422 '+nick+' :MOTD File is missing')
 while True:
  try:
   x=cl.recv(4096)
   if not x:break
   buf+=x
   while b'\n' in buf:
    line,buf=buf.split(b'\n',1); line=line.decode(errors='ignore').strip(); parts=line.split(); cmd=parts[0].upper() if parts else ''
    if cmd=='PASS': token=line[5:].strip()
    elif cmd=='NICK' and len(parts)>1:
     nick=parts[1]; register()
    elif cmd=='USER' and len(parts)>1:
     user=parts[1]; register()
    elif cmd=='PING':send(':huddle PONG huddle '+line.split(':',1)[-1])
    elif cmd=='PONG':pass
    elif cmd=='QUIT': return
    elif cmd in ('JOIN','NAMES','WHO','TOPIC','MODE') and len(parts)>1:
     chan=parts[1];c=conn(); z=chan[1:].split('/',1) if chan.startswith('#') else []
     ok=len(z)==2 and c.execute('SELECT 1 FROM workspaces w JOIN channels ch ON ch.workspace_id=w.id WHERE w.slug=? AND ch.name=?',(z[0],z[1])).fetchone()
     if cmd=='JOIN':
      if not ok:send(':huddle 403 '+nick+' '+chan+' :No such channel')
      else:
       joined.add(chan);send(':'+nick+'!user@huddle JOIN '+chan);send(':huddle 353 '+nick+' = '+chan+' :'+nick);send(':huddle 366 '+nick+' '+chan+' :End of NAMES list')
     elif cmd=='NAMES': send(':huddle 353 '+nick+' = '+chan+' :'+nick);send(':huddle 366 '+nick+' '+chan+' :End of NAMES list')
    elif cmd=='LIST':send(':huddle 323 '+nick+' :End of LIST')
    elif cmd=='PRIVMSG':pass
    elif cmd and registered:send(':huddle 421 '+nick+' '+cmd+' :Unknown command')
  except:break
 cl.close()
def main():
 c=conn();c.execute('CREATE TABLE IF NOT EXISTS irc_nicks(nick TEXT PRIMARY KEY)');c.commit();c.close()
 s=socket.socket();s.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1);s.bind(('0.0.0.0',6667));s.listen()
 while True:
  cl,_=s.accept();threading.Thread(target=serve,args=(cl,),daemon=True).start()
main()
